for d in [3,4]:
 L=[]
 for inds in itertools.combinations(range(7),d):
  for bits in range(1<<d):
   f=ALL
   for a,j in enumerate(inds):f&=V[j] if bits>>a&1 else ALL^V[j]
   L.append((f,[(sum(1<<j for j in inds),bits)]))
 P[d]=L

def randword(d):
 k=random.choices([1,2,3,4],[5,5,2,1])[0];qs=random.choices(P[d],k=k);f=0
 for z,_ in qs:f^=z
 return f,[q for _,L in qs for q in L]
def census(ds,N):
 C={}
 for it in range(N):
  # shared support feature by correlated XORs
  W=[randword(d) for d in ds]
  if random.random()<.5:
   # couple first2 same-degree entries
   W[1]=(W[0][0]^W[1][0],W[0][1]+W[1][1])
  fs=[q[0] for q in W]
  hist=tuple(( (fs[0] if i&1 else ALL^fs[0]) & (fs[1] if i&2 else ALL^fs[1]) & (fs[2] if i&4 else ALL^fs[2])).bit_count() for i in range(8))
