   assert len(support)==310
   print('FOUND',it,time.time()-start,flush=True);json.dump({'support':support},open('workspace/a1_ideal310.json','w'));pickle.dump((S,G,rows,a,b,c),open('workspace/a1_ideal310.pkl','wb'));raise SystemExit
 if it%10000==0:print(it,time.time()-start,flush=True)
